    private fun icon(name: String, vararg paths: Pair<Color, String>, w: Float = 24f, h: Float = 24f): ImageVector {
        val b = ImageVector.Builder(name, defaultWidth = 24.dp, defaultHeight = 24.dp * (h / w), viewportWidth = w, viewportHeight = h)
        for ((c, d) in paths) b.addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(c))
        return b.build()
    }

